<script setup lang="ts">import{computed}from'vue';import type{DecisionAnalysis}from'../../core/models';import{GROUP_GAP}from'../../core/candidate-groups';import RegretCurve from'./RegretCurve.vue';const props=defineProps<{analysis:DecisionAnalysis;stale:boolean}>();const groups=computed(()=>props.analysis.groups??[]);function groupOf(optionId:string){return groups.value.find(g=>g.optionIds.includes(optionId))}function badge(optionId:string){const group=groupOf(optionId);if(!group)return'';const index=groups.value.indexOf(group);return group.gapToBest===0?`第 1 梯队${group.optionIds.length>1?' · 难以区分':''}`:`第 ${index+1} 梯队 · 落后约 ${group.gapToBest} 分`}function rawTitle(item:DecisionAnalysis['options'][number]){return item.rawTotal==null?'':`未舍入总分 ${item.rawTotal.toFixed(1)}`}</script>
<template><section class="results"><div v-if="stale" class="stale-note">输入已变化，下方是上一次分析结果，请重新计算。</div><div class="recommendation"><span>THE LEAST REGRETFUL PATH</span><h2>最不后悔建议</h2><p>{{analysis.recommendation}}</p><small class="basis">判定依据：未舍入总分（整数仅为显示取整），差距小于 {{GROUP_GAP}} 分视为难以区分；名次、分组与建议同源。</small><aside v-for="notice in analysis.notices" :key="notice">{{notice}}</aside></div><RegretCurve :options="analysis.options"/><div class="score-grid"><article v-for="(item,index) in analysis.options" :key="item.option.id"><span>#0{{index+1}}</span><h3>{{item.option.name}}</h3><b :title="rawTitle(item)">{{item.total}}<small>/100</small></b><em v-if="badge(item.option.id)" class="group-badge">{{badge(item.option.id)}}</em><div><i v-for="p in item.points" :key="p.horizon">{{p.horizon}}年 {{p.score}}</i></div></article></div><div class="rehearsals"><article v-for="item in analysis.options" :key="item.option.id"><h3>{{item.option.name}} · 后悔预演</h3><div v-for="card in item.cards" :key="card.horizon"><b>{{card.horizon}} 年后</b><p>{{card.regret}}</p><small>{{card.trigger}} {{card.reversibility}}；{{card.action}}</small></div></article></div></section></template>
